/// <summary>
/// InventPriceMap map extension class
/// </summary>
[ExtensionOf(mapstr(InventPriceMap))]
final class NDXInventPriceMap_Extension
{
}

Method.Source:
/// <summary>
/// Calculates price per quantity
/// </summary>
/// <param name = "qty">Quantity</param>
/// <returns>Price</returns>
public Price KCS_PricePerQty(Qty qty)
{
    Price qtyPrice = this.Price() * qty / this.priceUnit();

    if (this.AllocateMarkup)
    {
        qtyPrice += (this.markup() / this.priceQty()) * qty;
    }

    return qtyPrice;
}
